create function public.valid_cebu_location(address jsonb) returns boolean language sql immutable set search_path='' as $body$
 select coalesce(
  jsonb_typeof(address)='object'
  and address ?& array['barangay','street','postal_code']
  and jsonb_typeof(address->'barangay')='string'
  and jsonb_typeof(address->'street')='string'
  and jsonb_typeof(address->'postal_code')='string'
  and (not(address ? 'city_code') or jsonb_typeof(address->'city_code')='string')
  and char_length(address->>'street')<=200
  and (address->>'postal_code'='' or address->>'postal_code' ~ '^[0-9]{4}$')
  and (case when address->>'city_code'='' then address->>'barangay'=''
    else public.cebu_location_name(coalesce(address->>'city_code','0730600000')) is not null
